from tree import Node

def find_tree_height(tree):
    # Base case: the empty subtree has height -1, so a lone leaf is 1 + max(-1, -1) = 0.
    if tree is None:
        return -1
    return 1 + max(find_tree_height(tree.get_left_child()),
                   find_tree_height(tree.get_right_child()))

