from tree import Node

def is_heap(tree, compare_func):
    for child in (tree.get_left_child(), tree.get_right_child()):
        if child is not None:
            # This child must relate correctly to its parent...
            if not compare_func(child.get_value(), tree.get_value()):
                return False
            # ...and the whole subtree rooted at the child must also be a heap.
            if not is_heap(child, compare_func):
                return False
    return True

