import json
import ps4b

def get_story_string():
    with open('story.txt', 'r') as f:
        story = str(f.read())
    return story[:-1]

def get_story_pads():
    with open('pads.txt') as json_file:
        return json.load(json_file)

def load_words(file_name):
    with open(file_name, 'r') as inFile:
        wordlist = []
        for line in inFile:
            wordlist.extend([word.lower() for word in line.split(' ')])
        return wordlist

def is_word(word_list, word):
    word = word.strip(" !@#$%^&*()-_+={}[]|\\:;'<>?,./\"").lower()
    return word in word_list

_WORDS = load_words('words.txt')

def decrypt_message_try_pads(ciphertext, pads):
    best_msg = None
    best_count = -1
    for pad in pads:
        pm = ciphertext.decrypt_message(pad)
        count = sum(1 for token in pm.get_text().split(' ') if is_word(_WORDS, token))
        if count >= best_count:
            best_count = count
            best_msg = pm
    return best_msg

def decode_story():
    story = ps4b.EncryptedMessage(get_story_string())
    pads = get_story_pads()
    return decrypt_message_try_pads(story, pads).get_text()

